#include <stdio.h>

struct Sample {
    int id;
    int millivolts;
};

int main(void)
{
    struct Sample current = { .id = 14, .millivolts = 320 };
    struct Sample archived = current;
    current.millivolts += 15;
    printf("%d %d %d\n", current.id, current.millivolts, archived.millivolts);
    return 0;
}

