#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

struct Sensor {
    int id;
    int reading;
};

int main(void)
{
    int value[3];
    const int minimum[] = {1, 0, -200};
    const int maximum[] = {9999, 2000, 200};
    if (!read_values(value, minimum, maximum, 3)) {
        puts("invalid");
        return 0;
    }
    struct Sensor active = { .id = value[0], .reading = value[1] };
    const struct Sensor original = active;
    int adjusted = active.reading; /* TODO: apply the correction. */
